# -*- coding: utf-8 -*-
from gen2 import *

m1 = M(('Виды треугольников', 'Kinds of triangles'),
 [('r', 'a', 'Сторона a', 'Side a', 1, 12, 1, 5), ('r', 'b', 'Сторона b', 'Side b', 1, 12, 1, 6), ('r', 'c', 'Сторона c', 'Side c', 1, 12, 1, 7)],
 [('Существует ли', 'Does it exist'), ('По сторонам', 'By sides'), ('По углам', 'By angles')],
 'Треугольник можно построить, если каждая сторона меньше суммы двух других. Вид зависит от равных сторон и наибольшего угла.', 'A triangle exists if each side is less than the sum of the other two. The kind depends on equal sides and the largest angle.', ('Треугольник по трём сторонам', 'A triangle from three sides'),
 r'''const T=triSides(v.a,v.b,v.c);if(!T)return {svg:TX(300,110,U("такого треугольника нет","no such triangle"),COL.a,22,"middle",600),st:[U("нет","no"),"—","—"],fb:U("Одна сторона не меньше суммы двух других.","One side is not less than the sum of the other two.")};
 const P=fitPts(T,60,20,480,190),a2=[v.a*v.a,v.b*v.b,v.c*v.c].sort((x,y)=>x-y),eq=(v.a===v.b?1:0)+(v.b===v.c?1:0)+(v.a===v.c?1:0);
 let g=poly(P,"#f4dfd8",COL.ink,3);const nm=["A","B","C"];P.forEach((p,i)=>g+=TX(p[0]+(i===1?14:i===0?-14:0),p[1]+(i===2?-10:18),nm[i],COL.ink,15,"middle",700));
 const kd=a2[0]+a2[1]===a2[2]?U("прямоугольный","right-angled"):a2[0]+a2[1]<a2[2]?U("тупоугольный","obtuse"):U("остроугольный","acute");
 return {svg:g,st:[U("да","yes"),eq===3?U("равносторонний","equilateral"):eq?U("равнобедренный","isosceles"):U("разносторонний","scalene"),kd],fb:U("Сравните квадрат большей стороны с суммой квадратов двух других.","Compare the square of the longest side with the sum of squares of the other two.")}''', '0 0 600 230')

m2 = M(('Признаки равенства треугольников', 'Congruence tests'),
 [('s', 'k', 'Признак', 'Test', ['ССС: три стороны', 'СУС: 2 стороны и угол', 'УСУ: сторона и 2 угла'], ['SSS: three sides', 'SAS: 2 sides + angle', 'ASA: side + 2 angles'], 1), ('r', 'a', 'Данные 1', 'Data 1', 3, 9, 1, 6), ('r', 'b', 'Данные 2', 'Data 2', 3, 9, 1, 5)],
 [('Что известно', 'What is known'), ('Третья сторона / угол', 'The third side / angle'), ('Вывод', 'Conclusion')],
 'Если три элемента одного треугольника равны трём элементам другого (по признаку), треугольники равны — совпадут при наложении.', 'If three elements of one triangle equal three of another (by a test), the triangles are congruent — they coincide when overlaid.', ('Два треугольника с равными данными', 'Two triangles with equal data'),
 r'''let T,info,third;const a=v.a,b=v.b,c=Math.min(a+b-1,Math.max(Math.abs(a-b)+1,6));
 if(v.k===0){T=triSides(a,b,c)||triSides(5,5,5);info=U("a = "+a+", b = "+b+", c = "+c,"a = "+a+", b = "+b+", c = "+c);third=U("все стороны даны","all sides given")}
 else if(v.k===1){const ang=70,cc=Math.sqrt(a*a+b*b-2*a*b*Math.cos(deg(ang)));T=[[0,0],[a,0],[b*Math.cos(deg(ang)),b*Math.sin(deg(ang))]];info=U("a = "+a+", b = "+b+", угол 70°","a = "+a+", b = "+b+", angle 70°");third=U("c = "+fnum(cc,2),"c = "+fnum(cc,2))}
 else{const A1=50,B1=60,C1=70;const k=a/Math.sin(deg(C1));const bb=k*Math.sin(deg(B1)),cc=k*Math.sin(deg(A1));T=triSides(a,bb,cc)||[[0,0],[a,0],[1,1]];info=U("сторона "+a+", углы 50° и 60°","a side "+a+", angles 50° and 60°");third=U("третий угол 70°","third angle 70°")}
 const P=fitPts(T,30,20,250,180,0.9),Q2=fitPts(T,320,20,250,180,0.9).map(p=>[p[0],p[1]]);
 const Q3=Q2.map(p=>[p[0],p[1]]);let g=poly(P,"#f4dfd8",COL.ink,3)+poly(Q3,"#dbe5f2",COL.ink,3)+TX(300,112,"=",COL.c,40,"middle",700);
 return {svg:g,st:[info,third,U("△ равны","triangles are congruent")],fb:U("Тройка равных элементов определяет треугольник однозначно.","Three equal elements determine the triangle uniquely.")}''', '0 0 600 230')

m3 = M(('Равнобедренный треугольник', 'The isosceles triangle'),
 [('r', 'ap', 'Угол при вершине, °', 'Apex angle, °', 20, 160, 1, 50)],
 [('Углы при основании', 'Base angles'), ('Высота — медиана — биссектриса', 'Altitude = median = bisector'), ('Сумма углов', 'Angle sum')],
 'В равнобедренном треугольнике углы при основании равны, а высота к основанию является и медианой, и биссектрисой.', 'In an isosceles triangle the base angles are equal and the altitude to the base is also the median and the bisector.', ('Равнобедренный треугольник с высотой', 'An isosceles triangle with its altitude'),
 r'''const ap=deg(v.ap),s=1,h=Math.cos(ap/2)*s,hb=Math.sin(ap/2)*s;const T=[[-hb,0],[hb,0],[0,h]],P=fitPts(T,100,15,400,190);const base=(180-v.ap)/2;
 let g=poly(P,"#f4dfd8",COL.ink,3)+L(P[2][0],P[2][1],P[2][0],P[0][1],COL.b,3)+TX(P[2][0]+18,P[2][1]+36,v.ap+"°",COL.a,14,"start",700)+TX(P[0][0]+24,P[0][1]-8,fnum(base,1)+"°",COL.a,14,"start",700)+TX(P[1][0]-24,P[1][1]-8,fnum(base,1)+"°",COL.a,14,"end",700);
 return {svg:g,st:[fnum(base,1)+"° и "+fnum(base,1)+"°",U("делит угол "+v.ap+"° на "+fnum(v.ap/2,1)+"° и "+fnum(v.ap/2,1)+"°","splits "+v.ap+"° into "+fnum(v.ap/2,1)+"° and "+fnum(v.ap/2,1)+"°"),v.ap+"° + 2·"+fnum(base,1)+"° = 180°"],fb:U("Углы при основании равны: (180° − угол при вершине) : 2.","The base angles are equal: (180° − apex angle) : 2.")}''', '0 0 600 230')

chapter('30', '30-triangles-congruence.html', 'V', ('Треугольники и признаки равенства', 'Triangles and congruence'),
 ('Какие бывают треугольники, когда два треугольника считают равными и почему равнобедренный треугольник «симметричен».', 'What triangles there are, when two triangles count as equal and why an isosceles triangle is “symmetric”.'),
 ('Мастер делает стропила для юрты: две одинаковые жерди должны сходиться в верхней точке под нужным углом. Основание лежит на земле.\n\nЧто нужно измерить, чтобы все такие треугольные рамы получились одинаковыми?', 'A craftsman makes rafters for a yurt: two identical poles must meet at the top at the right angle. The base lies on the ground.\n\nWhat must be measured so that all such triangular frames come out identical?'),
 ('Разгадка: три элемента', 'The answer: three elements'),
 ('Хватит трёх данных: либо трёх сторон, либо двух сторон и угла между ними, либо стороны и двух прилежащих углов. Это три признака равенства треугольников. Если у нескольких рам совпадают эти данные, все они получатся одинаковыми. Для равнобедренной рамы достаточно двух чисел: длины жерди и угла при вершине.', 'Three data are enough: either three sides, or two sides and the angle between them, or a side and its two adjacent angles. These are the three congruence tests. If several frames match in this data, they all come out identical. For an isosceles frame two numbers suffice: the pole length and the apex angle.'),
 [S('kinds', 'Виды треугольников', 'Kinds of triangles', ('По сторонам: <strong>разносторонний</strong>, <strong>равнобедренный</strong> (две стороны равны) и <strong>равносторонний</strong> (все равны). По углам: <strong>остроугольный</strong>, <strong>прямоугольный</strong> (есть угол 90°) и <strong>тупоугольный</strong> (есть угол больше 90°). Треугольник существует, если каждая сторона меньше суммы двух других.', 'By sides: <strong>scalene</strong>, <strong>isosceles</strong> (two sides equal) and <strong>equilateral</strong> (all equal). By angles: <strong>acute</strong>, <strong>right</strong> (has a 90° angle) and <strong>obtuse</strong> (has an angle above 90°). A triangle exists if each side is less than the sum of the other two.'),
    ('a < b + c', '', 'a < b + c'), m1),
  S('cong', 'Три признака равенства', 'Three congruence tests', ('Треугольники равны, если равны: 1) три стороны (<strong>ССС</strong>); 2) две стороны и угол между ними (<strong>СУС</strong>); 3) сторона и два прилежащих угла (<strong>УСУ</strong>). Равные треугольники можно совместить наложением, у них равны и все остальные элементы. Внимание: две стороны и угол <em>не между ними</em> признаком не являются.', 'Triangles are congruent if: 1) three sides are equal (<strong>SSS</strong>); 2) two sides and the included angle (<strong>SAS</strong>); 3) a side and two adjacent angles (<strong>ASA</strong>). Congruent triangles can be laid on each other, and all their other elements are equal too. Note: two sides and an angle <em>not between them</em> is not a test.'),
    ('ССС, СУС, УСУ', '', 'SSS, SAS, ASA'), m2),
  S('iso', 'Равнобедренный треугольник', 'The isosceles triangle', ('В равнобедренном треугольнике <strong>углы при основании равны</strong>, а высота, проведённая к основанию, является и медианой, и биссектрисой. Это следует из равенства двух половинок треугольника по признаку СУС. Равносторонний треугольник имеет углы по 60°.', 'In an isosceles triangle the <strong>base angles are equal</strong> and the altitude to the base is also a median and a bisector. This follows from the congruence of the two halves by SAS. An equilateral triangle has angles of 60°.'),
    ('∠B = ∠C', '', '∠B = ∠C'), m3)],
 [TK(('Существует ли', 'Does it exist'), ('Существует ли треугольник со сторонами 3, 4, 8?', 'Does a triangle with sides 3, 4, 8 exist?'), '3 + 4 = 7', '7 &lt; 8, значит нет.', ('Нет.', 'No.')),
  TK(('Вид', 'Kind'), ('Определите вид треугольника со сторонами 5, 12, 13.', 'Determine the kind of the triangle with sides 5, 12, 13.'), '25 + 144 = 169', '5² + 12² = 13², значит прямоугольный.', ('Прямоугольный.', 'Right-angled.')),
  TK(('Признак', 'Test'), ('По какому признаку равны треугольники, у которых 5 см, 7 см и угол между ними 40°?', 'By which test are triangles congruent if they have 5 cm, 7 cm and an included angle of 40°?'), '', 'Две стороны и угол между ними — СУС.', ('СУС.', 'SAS.')),
  TK(('Равнобедренный', 'Isosceles'), ('В равнобедренном треугольнике угол при вершине 40°. Найдите углы при основании.', 'In an isosceles triangle the apex angle is 40°. Find the base angles.'), '(180° − 40°) : 2', '140° : 2 = 70°.', '70°.'),
  TK(('Периметр', 'Perimeter'), ('Основание равнобедренного треугольника 8, боковая сторона 5. Периметр?', 'The base of an isosceles triangle is 8, a leg is 5. The perimeter?'), '', '8 + 5 + 5 = 18.', '18.')],
 [Q('Равносторонний треугольник имеет все углы по', 'An equilateral triangle has all angles of', '60°', '90°', '45°', ('180° : 3.', '180° : 3.')),
  Q('Сколько равных сторон у равнобедренного (минимум)?', 'How many equal sides does an isosceles triangle have (at least)?', '2', '1', '3', ('Две боковые.', 'The two legs.')),
  Q('СУС означает равенство', 'SAS means equality of', ('двух сторон и угла между ними', 'two sides and the included angle'), ('трёх углов', 'three angles'), ('двух углов и любой стороны', 'two angles and any side'), ('Сторона–угол–сторона.', 'Side–angle–side.')),
  Q('Равенство трёх углов даёт', 'Equality of three angles gives', ('подобие, но не равенство', 'similarity, not congruence'), ('равенство', 'congruence'), ('ничего', 'nothing'), ('Размеры могут различаться.', 'Sizes may differ.')),
  Q('Стороны 2, 3, 6. Треугольник', 'Sides 2, 3, 6. The triangle', ('не существует', 'does not exist'), ('существует', 'exists'), ('прямоугольный', 'is right-angled'), ('2 + 3 &lt; 6.', '2 + 3 &lt; 6.')),
  Q('Углы при основании равнобедренного', 'The base angles of an isosceles triangle', ('равны', 'are equal'), ('разные', 'differ'), ('по 90°', '90° each'), ('Свойство равнобедренного.', 'The isosceles property.')),
  Q('Высота к основанию равнобедренного — это ещё и', 'The altitude to the base of an isosceles triangle is also', ('медиана и биссектриса', 'the median and the bisector'), ('диагональ', 'a diagonal'), ('радиус', 'a radius'), ('Свойство.', 'The property.')),
  Q('Тупоугольный треугольник имеет угол', 'An obtuse triangle has an angle', ('больше 90°', 'greater than 90°'), ('равный 90°', 'equal to 90°'), ('меньше 30°', 'less than 30°'), ('По определению.', 'By definition.'))],
 src=[('Wikipedia: Congruence (geometry)', 'https://en.wikipedia.org/wiki/Congruence_(geometry)'), ('Wikipedia: Isosceles triangle', 'https://en.wikipedia.org/wiki/Isosceles_triangle')])
